import{_ as t,l as c,o as a,c as l,v as r,p as i,x as o,d,i as n,S as u}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"acquire / release","description":"","frontmatter":{"title":"acquire / release","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/acquire-release.md","filePath":"cs/acquire-release.md","lastUpdated":1789023840000}'),m={name:"cs/acquire-release.md"};function p(h,e,q,_,f,A){const s=c("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="acquire-release" tabindex="-1">acquire / release <a class="header-anchor" href="#acquire-release" aria-label="Permalink to &quot;acquire / release&quot;">​</a></h1><div class="epigraph"><p>释放之前的写必须在锁释放这一刀之前对全局可见；获取之后的读必须在锁获取这一刀之后才开始。不必对全世界做全序栅栏。</p><footer>—— 据 Boehm and Adve, Foundations of the C++ Concurrency Memory Model, PLDI 2008；SPARC RMO 整理</footer></div><p><a href="/cs/atomic-cache-impl">上一课</a> 保证单个地址的 RMW 不被切开。程序员写互斥时还需要：<strong>解锁之前对共享数据的 store，要被下一位加锁成功的人的 load 看见。</strong> <a href="/cs/mesi-protocol">MESI</a> 不管两个地址之间的顺序。本课不重做 cache lock。缺口是<strong>acquire/release：比 seq-cst 全栅栏弱、比 relaxed 强的单向屏障。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核 A：<code>data=1; unlock</code>。核 B：<code>lock; x=data</code>。若 <code>unlock</code> 的 store 与 <code>data</code> 的 store 在写缓冲里重排，B 可能看到锁已开、<code>data</code> 仍是 0。seq-cst fence 能修，但把无关的访存也挡住，<a href="/cs/mlp-memory-parallelism">MLP</a> 与 store 缓冲收益尽失。缺口不是更重的原子，而是<strong>释放：此前写不能越过释放；获取：此后读不能越过获取。</strong></p><p><span class="marginnote">C++11 / RISC-V 的 <code>release</code>/<code>acquire</code>、ARM 的 <code>dmb ishld</code> 一类，都是这个单向约束。x86 TSO 对 store 已经很强，许多释放几乎免费，获取仍要限制 store 前的 load 重排——实现上常已满足。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>微结构：release store 在 SQ 里等到更年长的 store 都变成一致性可见（drain 到某一点）再发出；acquire load 之后的访存等该 load 完成（至少数据返回且获得足够权限）。不必等全世界的无关行。与 <a href="/cs/write-combining">写合并</a>：WC 区域的 drain 规则更严，release 往往强制冲刷 WCB。</p>',8)),(a(),i(u,null,{default:o(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E6%9B%B4%E5%B9%B4%E9%95%BF%E7%9A%84%20store%22%5D%20--%3E%20REL%5B%22release%22%5D%0A%20%20REL%20--%3E%20UNL%5B%22%E9%94%81%E5%AD%97%E5%8F%AF%E8%A7%81%22%5D%0A%20%20ACQ%5B%22acquire%20%E9%94%81%E5%AD%97%22%5D%20--%3E%20LD%5B%22%E6%9B%B4%E5%B9%B4%E8%BD%BB%E7%9A%84%20load%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这是内存模型与 cache 协议的接口：协议提供单行上的「可见」，模型把多行用 acquire/release 串起来。乱序核的 <a href="/cs/lsq-disambiguation">LSQ</a> 必须禁止跨越这些点的投机重排，或在发现违规时 replay。比下一课事务内存弱：这里没有多行原子提交，只有顺序约束。</p><p>relaxed 原子只保证该地址 RMW 的原子性，不提供这把「刀」。seq-cst 在所有核上插一把全序，实现上接近更重的 fence。锁的正确写法是 release 解锁、acquire 加锁，数据本身用普通访存即可——数据竞争自由程序的编译器契约。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 的 memory_order 矩阵整页抄来。也不把 Linux <code>smp_mb</code> 的各种变体列全。事务内存试图把临界区里的多行读写作一个原子块，失败则 abort，下一课。fence 指令的微结构代价再下一课单独记账。</p><p>后课默认：锁配对用 acquire/release 即可表达可见性，不必每条访存 seq-cst。把整个临界区包成硬件事务是另一条路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>acquire/release 是单向屏障，服务锁的可见性，弱于全序 fence。</li><li>实现上主要约束 SQ drain 与后续访存的发射。</li><li>多行投机原子块是下一课事务内存。</li><li>出处：Boehm and Adve, <em>PLDI</em>, 2008；SPARC RMO；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const S=t(m,[["render",p]]);export{E as __pageData,S as default};
